/// Seconds of media generated and published.
const MEDIA_SECONDS: u32 = 12;
/// Publish at this multiple of real time (HLS cuts on media timestamps).
const PUBLISH_SPEEDUP: u32 = 3;
/// Generous: covers container start, x264 and two 4 s segments.
const HLS_TIMEOUT: Duration = Duration::from_secs(90);

fn required_env(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| {
        panic!("{name} is not set: run tests/real_media/run.sh (a missing ffmpeg must fail, never skip)")
    })
}

/// Runs `tool args...`, failing with its stderr unless it exits 0.
async fn run_tool(tool: &str, args: &[&str]) -> String {
    let output = tokio::process::Command::new(tool)
        .args(args)
        .stdin(std::process::Stdio::null())
        .output()
        .await
        .unwrap_or_else(|e| panic!("spawn {tool}: {e}"));
    assert!(
        output.status.success(),
        "{tool} {args:?} failed ({}): {}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    // `-v error` decode checks must be silent: any stderr is a decode error.
    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();
    assert!(stderr.trim().is_empty(), "{tool} reported errors: {stderr}");
    String::from_utf8_lossy(&output.stdout).into_owned()
}

/// Generates `MEDIA_SECONDS` of real H.264 (1 s GOP) + AAC as an FLV file.
async fn generate_flv(ffmpeg: &str, out: &Path) {
    let seconds = MEDIA_SECONDS.to_string();
    run_tool(
        ffmpeg,
        &[
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "testsrc=size=320x240:rate=25",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:sample_rate=44100",
            "-t",
            &seconds,
            "-c:v",
            "libx264",
            "-preset",
            "ultrafast",
            "-pix_fmt",
            "yuv420p",
            "-g",
            "25",
            "-keyint_min",
            "25",
            "-sc_threshold",
            "0",
            "-c:a",
            "aac",
            "-b:a",
            "64k",
            "-f",
            "flv",
            &out.to_string_lossy(),
        ],
    )
    .await;
}

/// One FLV tag: (tag type, timestamp ms, payload).
type FlvTag = (u8, u32, Bytes);

/// Splits an FLV file into its tags (9-byte header, then
/// `PrevTagSize | tag header (11) | payload` repeated).
fn parse_flv(bytes: &[u8]) -> Vec<FlvTag> {
    assert!(bytes.len() > 13 && &bytes[..3] == b"FLV", "not an FLV file");
    let mut pos = 9 + 4;
    let mut tags = Vec::new();
    while pos + 11 <= bytes.len() {
        let tag_type = bytes[pos];
        let size = u32::from_be_bytes([0, bytes[pos + 1], bytes[pos + 2], bytes[pos + 3]]) as usize;
        let ts = u32::from_be_bytes([
            bytes[pos + 7],
            bytes[pos + 4],
            bytes[pos + 5],
            bytes[pos + 6],
        ]);
        let start = pos + 11;
        let end = start + size;
        assert!(end + 4 <= bytes.len(), "truncated FLV tag");
        tags.push((tag_type, ts, Bytes::copy_from_slice(&bytes[start..end])));
        pos = end + 4;
    }
    tags
}

struct Scenario {
    transcode: bool,
    stream_key: &'static str,
    community_id: i32,
    /// Also the pipeline id: `Uuid::from_u128(config_id)`.
    config_id: u128,
}

/// Sets up the real service pieces, publishes real media and returns the
/// extracted evidence by asserting inline.
async fn run_scenario(sc: Scenario) {
    let logs = LogCapture::install();
    let ffmpeg = required_env("SVC_STREAMING_REAL_FFMPEG");
    let ffprobe = required_env("SVC_STREAMING_REAL_FFPROBE");
    let workdir =
        PathBuf::from(required_env("SVC_STREAMING_REAL_WORKDIR")).join(Uuid::new_v4().to_string());
    std::fs::create_dir_all(&workdir).expect("create scenario workdir");
    let stream_data_dir = workdir.join("data");
    std::fs::create_dir_all(&stream_data_dir).expect("create stream data dir");
    // `db::get_or_connect` caches ONE process-global connection, so both
    // scenarios (separate tests, one process) share this database file.
    let db_path = std::env::temp_dir().join(format!(
        "svc-streaming-real-media-{}.sqlite",
        std::process::id()
    ));

    // SAFETY: set before any await; both scenarios set the same value.
    unsafe { std::env::set_var("DB_TYPE", "sqlite") };

    let flv_path = workdir.join("input.flv");
    generate_flv(&ffmpeg, &flv_path).await;
    let tags = parse_flv(&std::fs::read(&flv_path).expect("read generated flv"));
    let media_tags = tags.iter().filter(|t| t.0 == 8 || t.0 == 9).count();
    assert!(
        media_tags > 100,
        "generated media looks empty: {media_tags} tags"
    );
    println!(
        "generated {} flv tags ({media_tags} audio/video)",
        tags.len()
    );

    let cli = CliConfig::try_parse_from([
        "svc-streaming",
        "--db-name",
        &db_path.to_string_lossy(),
        "--stream-data-dir",
        &stream_data_dir.to_string_lossy(),
        "--ffmpeg-path",
        &ffmpeg,
        "--webrtc-udp-range",
        "45600-45610",
    ])
    .expect("valid cli assembly");
    let config = Config {
        cli,
        db_password: Secret::new("unused"),
        cache_password: None,
        service_api_key: Secret::new("unused"),
        jwt_hmac_secret: None,
    };

    let db = svc_streaming::db::get_or_connect(&config)
        .await
        .expect("sqlite connection");
    let transcode = i32::from(sc.transcode);
    db.execute_unprepared(&format!(
        r#"
        CREATE TABLE IF NOT EXISTS tenants (id INTEGER PRIMARY KEY, slug TEXT NOT NULL UNIQUE);
        CREATE TABLE IF NOT EXISTS communities (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS streaming_configs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            community_id INTEGER NOT NULL UNIQUE,
            source_url TEXT NOT NULL,
            source_type TEXT NOT NULL DEFAULT 'rtmp',
            enabled INTEGER NOT NULL DEFAULT 1,
            record_enabled INTEGER NOT NULL DEFAULT 0,
            transcode_enabled INTEGER NOT NULL DEFAULT 0,
            transcode_bitrate_kbps INTEGER NOT NULL DEFAULT 4000,
            video_codec TEXT NOT NULL DEFAULT 'h264',
            audio_codec TEXT NOT NULL DEFAULT 'copy'
        );
        CREATE TABLE IF NOT EXISTS streaming_targets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            config_id INTEGER NOT NULL,
            platform TEXT NOT NULL,
            forward_url TEXT NOT NULL,
            enabled INTEGER NOT NULL DEFAULT 1,
            protocol TEXT NOT NULL DEFAULT 'rtmp',
            video_codec TEXT,
            audio_codec TEXT
        );
        INSERT OR IGNORE INTO tenants (id, slug) VALUES (1, 'tenant-1');
        INSERT OR REPLACE INTO communities (id, tenant_id) VALUES ({cid}, 1);
        INSERT OR REPLACE INTO streaming_configs (id, community_id, source_url, enabled, record_enabled, transcode_enabled, transcode_bitrate_kbps)
            VALUES ({config_id}, {cid}, '{key}', 1, 0, {transcode}, 800);
        "#,
        cid = sc.community_id,
        config_id = sc.config_id,
        key = sc.stream_key,
    ))
    .await
    .expect("seed schema");

    let prom = prometheus::Registry::new();
    let supervisor = Arc::new(FfmpegSupervisor::new(
        PathBuf::from(&ffmpeg),
        stream_data_dir.clone(),
        45600,
        Arc::new(DefaultSecretResolver),
        SupervisorConfig::default(),
    ));
    let hls = Arc::new(HlsSink::with_intervals(
        stream_data_dir.clone(),
        &prom,
        Duration::from_millis(200),
        svc_streaming::egress::hls::DEFAULT_CLEANUP_DELAY,
    ));
    let registry = Arc::new(PipelineRegistry::new());
    let relay = Arc::new(RelaySink::new());
    let rtc_config = RtcConfig::from_config(&config).expect("valid webrtc_udp_range");
    let factory = Arc::new(PeerConnectionFactory::new(rtc_config).expect("factory builds"));
    let (whip_tx, _whip_rx) = mpsc::channel(1);
    let whip_state = Arc::new(WhipState::new(
        factory,
        Arc::new(InternalIngestAuthClient::new(&config).expect("loopback client")),
        whip_tx,
        config.cli.stream_data_dir.clone(),
        config.cli.bind_addr,
        RtcMetrics::register(&prometheus::Registry::new()).expect("registers once"),
    ));
    let orchestrator = Arc::new(Orchestrator::new(
        config.clone(),
        supervisor,
        hls,
        relay,
        None,
        registry.clone(),
        whip_state,
    ));
    let (ingest_tx, ingest_rx) = mpsc::channel(4);
    tokio::spawn(Arc::clone(&orchestrator).run(ingest_rx));
    let listener = RtmpListener::bind(
        IpAddr::V4(Ipv4Addr::LOCALHOST),
        0,
        Arc::new(DbIngestAuth::new(config.clone())),
        &prom,
    )
    .await
    .expect("rtmp listener binds");
    let rtmp_addr = listener.local_addr().expect("local_addr");
    tokio::spawn(listener.run(ingest_tx));

    // Publish the real media over RTMP, paced at PUBLISH_SPEEDUP x real time.
    let mut stream = TcpStream::connect(rtmp_addr).await.expect("connect rtmp");
    let mut session = tokio::time::timeout(
        Duration::from_secs(10),
        connect_and_publish(&mut stream, "live", sc.stream_key),
    )
    .await
    .expect("publish flow completes in time")
    .expect("publish accepted");
    let started = tokio::time::Instant::now();
    for (tag_type, ts, payload) in tags.into_iter().filter(|t| t.0 == 8 || t.0 == 9) {
        tokio::time::sleep_until(started + Duration::from_millis(u64::from(ts / PUBLISH_SPEEDUP)))
            .await;
        let result = if tag_type == 9 {
            session.publish_video_data(payload, RtmpTimestamp::new(ts), false)
        } else {
            session.publish_audio_data(payload, RtmpTimestamp::new(ts), false)
        }
        .expect("publish media tag");
        write_client_result(&mut stream, result).await;
    }

    let pipeline_id = Uuid::from_u128(sc.config_id);
    let hls_dir = stream_data_dir
        .join("hls")
        .join(pipeline_id.to_string())
        .join("default");
    let playlist = hls_dir.join("index.m3u8");

    // 1. The playlist appears and lists >= 2 segments (connection stays open:
    //    the stream is still live, no ENDLIST finalisation is relied upon).
    let deadline = tokio::time::Instant::now() + HLS_TIMEOUT;
    let segments = loop {
        let text = std::fs::read_to_string(&playlist).unwrap_or_default();
        let listed: Vec<String> = text
            .lines()
            .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
            .map(str::to_owned)
            .collect();
        if listed.len() >= 2 && listed.iter().all(|s| hls_dir.join(s).exists()) {
            break listed;
        }
        assert!(
            tokio::time::Instant::now() < deadline,
            "index.m3u8 never listed >= 2 existing segments within {HLS_TIMEOUT:?}; playlist:\n{text}\ndir: {:?}\nlogs:\n{}",
            std::fs::read_dir(&hls_dir).map(|d| d.flatten().map(|e| e.file_name()).collect::<Vec<_>>()),
            logs.text()
        );
        tokio::time::sleep(Duration::from_millis(250)).await;
    };
    println!("playlist lists {} segments: {segments:?}", segments.len());
    assert!(hls_dir.join("master.m3u8").exists(), "master.m3u8 missing");
    assert!(
        hls_dir.join("init.mp4").exists(),
        "fMP4 init segment missing"
    );

    // 2. The public HLS router serves the playlist and a segment as on disk.
    let app = hls_router(HlsRouterState::new(
        stream_data_dir.clone(),
        registry.clone() as Arc<dyn RunningPipelines>,
    ));
    for (name, expect_ct) in [("index.m3u8", "application/vnd.apple.mpegurl")] {
        let res = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!(
                        "/live/{}/{pipeline_id}/default/{name}",
                        sc.community_id
                    ))
                    .body(AxumBody::empty())
                    .expect("request"),
            )
            .await
            .expect("router response");
        assert_eq!(res.status(), StatusCode::OK, "{name}");
        assert_eq!(
            res.headers().get("content-type").expect("content-type"),
            expect_ct
        );
    }
    let first = &segments[0];
    let res = app
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/live/{}/{pipeline_id}/default/{first}",
                    sc.community_id
                ))
                .body(AxumBody::empty())
                .expect("request"),
        )
        .await
        .expect("router response");
    assert_eq!(res.status(), StatusCode::OK, "segment {first}");
    let served = res.into_body().collect().await.expect("body").to_bytes();
    assert_eq!(
        served.as_ref(),
        std::fs::read(hls_dir.join(first)).expect("read segment")
    );
    assert!(
        served.len() > 1000,
        "segment suspiciously small: {}",
        served.len()
    );

    // 3. Real ffprobe/ffmpeg: codecs, duration, clean decode.
    let playlist_str = playlist.to_string_lossy().into_owned();
    let probe = run_tool(
        &ffprobe,
        &[
            "-v",
            "error",
            "-allowed_extensions",
            "ALL",
            "-show_entries",
            "stream=codec_name,codec_type,width,height",
            "-of",
            "json",
            &playlist_str,
        ],
    )
    .await;
    let probe: serde_json::Value = serde_json::from_str(&probe).expect("ffprobe json");
    let codec_of = |kind: &str| {
        probe["streams"]
            .as_array()
            .expect("streams")
            .iter()
            .find(|s| s["codec_type"] == kind)
            .and_then(|s| s["codec_name"].as_str().map(str::to_owned))
            .unwrap_or_else(|| panic!("no {kind} stream in {probe}"))
    };
    assert_eq!(codec_of("video"), "h264");
    assert_eq!(codec_of("audio"), "aac");
    let video = probe["streams"]
        .as_array()
        .expect("streams")
        .iter()
        .find(|s| s["codec_type"] == "video")
        .expect("video");
    assert_eq!(
        (video["width"].as_u64(), video["height"].as_u64()),
        (Some(320), Some(240))
    );

    // A live playlist (no ENDLIST) has no container duration, so measure the
    // video packets: span from first pts to last pts + frame duration.
    let packets = run_tool(
        &ffprobe,
        &[
            "-v",
            "error",
            "-allowed_extensions",
            "ALL",
            "-select_streams",
            "v:0",
            "-show_entries",
            "packet=pts_time,duration_time",
            "-of",
            "json",
            &playlist_str,
        ],
    )
    .await;
    let packets: serde_json::Value = serde_json::from_str(&packets).expect("packets json");
    let times: Vec<(f64, f64)> = packets["packets"]
        .as_array()
        .expect("packets")
        .iter()
        .map(|p| {
            (
                p["pts_time"]
                    .as_str()
                    .expect("pts_time")
                    .parse()
                    .expect("f64"),
                p["duration_time"]
                    .as_str()
                    .map_or(0.04, |d| d.parse().expect("f64")),
            )
        })
        .collect();
    assert!(
        times.len() >= 100,
        "only {} video packets decoded from {} segments",
        times.len(),
        segments.len()
    );
    let first = times.iter().map(|t| t.0).fold(f64::MAX, f64::min);
    let last = times.iter().map(|t| t.0 + t.1).fold(f64::MIN, f64::max);
    let duration = last - first;
    let listed_min = segments.len() as f64 * 3.0;
    assert!(
        (listed_min..=f64::from(MEDIA_SECONDS) + 1.0).contains(&duration),
        "duration {duration}s outside [{listed_min}, {}] for {} segments",
        MEDIA_SECONDS + 1,
        segments.len()
    );
    // The playlist's own EXTINF durations agree with the decoded span.
    let extinf: f64 = std::fs::read_to_string(&playlist)
        .expect("playlist")
        .lines()
        .filter_map(|l| l.strip_prefix("#EXTINF:"))
        .map(|d| d.trim_end_matches(',').parse::<f64>().expect("EXTINF f64"))
        .sum();
    assert!(
        (extinf - duration).abs() < 2.5,
        "EXTINF sum {extinf}s vs decoded {duration}s"
    );
    println!(
        "ffprobe: duration {duration:.2}s, h264+aac, {} segments",
        segments.len()
    );
    // Full decode: `-v error` must stay silent (run_tool asserts empty stderr).
    run_tool(
        &ffmpeg,
        &[
            "-v",
            "error",
            "-allowed_extensions",
            "ALL",
            "-i",
            &playlist_str,
            "-f",
            "null",
            "-",
        ],
    )
    .await;

    // The encode path is the one the scenario asked for (the supervisor logs
    // the chosen encoder per pipeline id): libx264 when transcoding, no
    // re-encode line at all for passthrough.
    let encode_line_for_this_pipeline = |needle: &str| {
        logs.text().lines().any(|l| {
            l.contains(&pipeline_id.to_string())
                && l.contains("pipeline encode")
                && l.contains(needle)
        })
    };
    assert_eq!(
        encode_line_for_this_pipeline("encoder=\"libx264\""),
        sc.transcode,
        "transcode={} but libx264 encode log presence disagrees",
        sc.transcode
    );

    // 4. The stream key never reached a log line; the capture is not empty.
    let on_disk_playlist = std::fs::read_to_string(&playlist).expect("playlist");
    assert!(
        !on_disk_playlist.contains(sc.stream_key),
        "stream key leaked into the playlist"
    );
    logs.assert_no_secret_leak(&[sc.stream_key], &[&fingerprint(sc.stream_key)]);

    // Teardown: stop the pipeline (real ffmpeg exits), drop the publisher.
    orchestrator.stop_pipeline(pipeline_id).await;
    drop(session);
    drop(stream);
    let _ = std::fs::remove_dir_all(&workdir);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn rtmp_publish_to_transcoded_hls_with_real_ffmpeg() {
    run_scenario(Scenario {
        transcode: true,
        stream_key: "sk_real_media_transcode_7f3a",
        community_id: 51,
        config_id: 1,
    })
    .await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn rtmp_publish_to_passthrough_hls_with_real_ffmpeg() {
    run_scenario(Scenario {
        transcode: false,
        stream_key: "sk_real_media_passthru_9c1d",
        community_id: 52,
        config_id: 2,
    })
    .await;
}
